package edu.campus.lostfound.web;
import edu.campus.lostfound.domain.*;import edu.campus.lostfound.repository.*;import edu.campus.lostfound.service.ClaimService;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import org.springframework.transaction.annotation.Transactional;
@Controller @RequestMapping("/admin") public class AdminController{
 private final ReportRepository reports;private final UserRepository users;private final AuditEventRepository audit;private final ClaimService claims;public AdminController(ReportRepository reports,UserRepository users,AuditEventRepository audit,ClaimService claims){this.reports=reports;this.users=users;this.audit=audit;this.claims=claims;}
 @GetMapping @Transactional(readOnly=true) String index(Model m){m.addAttribute("reports",reports.findByStatusOrderByCreatedAtDesc(ReportStatus.OPEN));m.addAttribute("claims",claims.pendingClaims());return "admin";}
 @PostMapping("/reports/{id}/status")@Transactional String status(@PathVariable Long id,@RequestParam ReportStatus status,Authentication auth,RedirectAttributes f){ItemReport report=reports.findById(id).orElseThrow();report.setStatus(status);audit.save(new AuditEvent(users.findByEmailIgnoreCase(auth.getName()).orElseThrow(),"REPORT_STATUS_"+status,"REPORT",id));f.addFlashAttribute("notice","Report status updated.");return "redirect:/admin";}
 @PostMapping("/claims/{id}/review")String reviewClaim(@PathVariable Long id,@RequestParam ClaimStatus decision,@RequestParam(defaultValue="")String adminNote,Authentication auth,RedirectAttributes f){claims.review(id,decision,auth.getName(),adminNote);f.addFlashAttribute("notice",decision==ClaimStatus.APPROVED?"Claim approved; both reports were marked resolved.":"Claim rejected and claimant notified.");return "redirect:/admin";}
}
